ORDERS = {1: [{"price": 10.0, "qty": 2}, {"price": 2.5, "qty": 1}]}


def total(items, discount=0.0):
    """Total of an order, in euros, after a discount between 0 and 1."""
    return sum(item["price"] * item["qty"] for item in items) * (1 - discount)


def get_order(order_id):
    if order_id not in ORDERS:
        raise KeyError("Not found")
    return ORDERS[order_id]

